#include <vector>
#include <complex>
#include <algorithm>
#include <omp.h>

void sortComplexByMagnitude(std::vector<std::complex<double>> &x) {
    const int n = static_cast<int>(x.size());
    if (n < 2) return;

    // Parallel odd-even transposition sort:
    // Safe under any thread count because each phase compares/swaps disjoint pairs.
    for (int phase = 0; phase < n; ++phase) {
        const int start = phase & 1; // even phase: 0, odd phase: 1

        #pragma omp parallel for default(none) shared(x, n, start)
        for (int i = start; i < n - 1; i += 2) {
            const std::complex<double> a = x[i];
            const std::complex<double> b = x[i + 1];

            const double ma = std::norm(a); // magnitude squared
            const double mb = std::norm(b);

            // Ascending by magnitude; tie-break by real then imag for deterministic ordering.
            if (ma > mb ||
                (ma == mb && (a.real() > b.real() ||
                             (a.real() == b.real() && a.imag() > b.imag())))) {
                x[i] = b;
                x[i + 1] = a;
            }
        }
        // Implicit barrier at end of omp for ensures phase completion before next phase.
    }
}
